const DIR_URL =
  "https://www.kma.go.kr/cgi-bin/aws/nph-aws_txt_min?0&0&MINDB_01M&0&a";

const DEFAULT_NX = 91; // 경남 거제시 아주동
const DEFAULT_NY = 69;
const DEFAULT_CODE = "294"; // 경남 거제시 장평동 (매칭 실패 시)

const CACHE_TTL = 60; // 관측 응답 캐시 1분
const DIR_CACHE_TTL = 86400; // 지점목록 캐시 1일
const HISTORY_MAX_LEN = 5;

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Cache-Control": "no-store",
};

/**
 * @typedef {Object} WorkerEnv
 * @property {{ get(): Promise<string> }} KMA_SERVICE_KEY  Secret Store 바인딩
 * @property {{ get(key: string): Promise<string | null>, put(key: string, value: string): Promise<void> }} WEATHER_HISTORY  Workers KV 바인딩
 */

export default {
  /**
   * @param {Request} request
   * @param {WorkerEnv} env
   * @param {{ waitUntil(promise: Promise<unknown>): void }} ctx
   */
  async fetch(request, env, ctx) {
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: CORS_HEADERS,
      });
    }

    if (request.method !== "GET") {
      return jsonResponse({ error: "Method Not Allowed" }, 405);
    }

    try {
      const url = new URL(request.url);

      const name = url.searchParams.get("name") || "";
      const codeParam = (url.searchParams.get("code") || "").trim();
      const nx = Math.round(Number(url.searchParams.get("nx"))) || DEFAULT_NX;
      const ny = Math.round(Number(url.searchParams.get("ny"))) || DEFAULT_NY;

      // 1. 관측소 지점 결정 (code 지정 시 우선, 아니면 name 매칭)
      const selected = codeParam
        ? { c: codeParam, n: "", a: "" }
        : await pickStation(env, name);

      const code = selected.c;

      const cache = caches.default;
      const cacheRequest = new Request(
        `https://kma-weather-cache.local/kma/${code}/${nx}/${ny}`
      );

      // 2. Worker 캐시 확인
      const cachedResponse = await cache.match(cacheRequest);
      if (cachedResponse) {
        return addCorsHeaders(cachedResponse);
      }

      // 3. 해당 지점 분 단위 관측 페이지 스크래핑
      const weather = await fetchStationObservation(code);

      // 실제 측정 위치(관측소 이름/주소)를 응답에 포함
      const meta = await stationMeta(selected);
      if (meta) {
        weather.station_name = meta.n || "";
        weather.station_addr = meta.a || "";
      }

      // 4. 풍속(예보격자) + 체감온도
      try {
        const windSpeed = await fetchWindSpeed(env, nx, ny);
        weather.wind_speed = windSpeed;
        weather.feels_like = calcFeelsLike(
          weather.temperature,
          weather.humidity,
          windSpeed
        );
      } catch (feelsErr) {
        weather.feels_like = null;
        weather.feels_like_error = feelsErr.message;
      }

      // 5. KV 히스토리 (지점별 분리)
      const history = await updateHistory(env, code, weather);

      const payload = { latest: weather, history };

      const result = new Response(JSON.stringify(payload), {
        status: 200,
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "Cache-Control": `public, max-age=${CACHE_TTL}`,
        },
      });

      ctx.waitUntil(cache.put(cacheRequest, result.clone()));

      return addCorsHeaders(result);
    } catch (error) {
      return jsonResponse(
        { error: error.message || "Unknown error" },
        500
      );
    }
  },
};

// ======================================================
// 관측소 선택 (주소 토큰 매칭)
// ======================================================

/**
 * @param {WorkerEnv} env
 * @param {string} name
 * @returns {Promise<{ c: string, n: string, a: string }>}
 */
async function pickStation(env, name) {
  if (!name) {
    return defaultStation();
  }

  const list = await loadStations();

  const code = matchStationCode(list, name);

  return (
    list.find((s) => s.c === code) ||
    STATIONS.find((s) => s.c === code) ||
    { c: code, n: "", a: "" }
  );
}

function defaultStation() {
  return (
    STATIONS.find((s) => s.c === DEFAULT_CODE) || {
      c: DEFAULT_CODE,
      n: "거제",
      a: "경상남도 거제시 장평동",
    }
  );
}

/**
 * code만 지정된 경우에도 관측소 이름/주소를 찾아 반환
 * @param {{ c: string, n?: string, a?: string }} selected
 * @returns {Promise<{ c: string, n: string, a: string } | null>}
 */
async function stationMeta(selected) {
  if (selected.n !== undefined && selected.n !== "") {
    return /** @type {{ c: string, n: string, a: string }} */ (selected);
  }

  const list = await loadStations();

  return (
    list.find((s) => s.c === selected.c) ||
    STATIONS.find((s) => s.c === selected.c) ||
    null
  );
}

// 주소/이름을 공백 기준 토큰으로 분리
// 예) "경상남도 거제시 장평동" → [경상남도, 거제시, 장평동]
function tokenize(addr) {
  return addr
    .replace(/\s+/g, " ")
    .trim()
    .split(" ")
    .filter(Boolean);
}

function matchStationCode(list, name) {
  const input = tokenize(name);
  const city = input.filter((t) => /[시군구]$/.test(t)).pop();
  const unit = input.filter((t) => /[읍면동]$/.test(t)).pop();

  let bestScore = 0;
  let candidates = [];

  for (const st of list) {
    const at = tokenize(st.a);
    const acity = at.filter((t) => /[시군구]$/.test(t)).pop();
    const aunit = at.filter((t) => /[읍면동]$/.test(t)).pop();

    let score = 0;
    if (unit && aunit && unit === aunit) score += 100;
    if (city && acity && city === acity) score += 40;
    // 시/군/구가 같은 광역시·도인지 가중치
    if (input[0] && at[0] && input[0] === at[0]) score += 5;

    if (score > bestScore) {
      bestScore = score;
      candidates = [st];
    } else if (score === bestScore && score > 0) {
      candidates.push(st);
    }
  }

  if (candidates.length === 0) {
    return DEFAULT_CODE;
  }

  if (candidates.length === 1) {
    return candidates[0].c;
  }

  // 동점자 처리: 지점명 == 시/군/구명(대표 관측소) 우선
  const base = city ? city.replace(/[시군구]$/, "") : "";
  const rep = candidates.find((s) => s.n === base);
  if (rep) {
    return rep.c;
  }

  // 광역시/특별시 등 광역단위: 지점명 == 광역시/도명 우선
  const metroBase = input[0].replace(
    /특별자치도|광역시|특별시|특별자치시$/,
    ""
  );
  const mrep = candidates.find((s) => s.n === metroBase);
  if (mrep) {
    return mrep.c;
  }

  candidates.sort((x, y) => Number(x.c) - Number(y.c));
  return candidates[0].c;
}

// ======================================================
// 전국 관측소 목록 (캐시 1일 → 실패 시 내장 데이터)
// ======================================================

function dirCacheKey() {
  return "https://kma-weather-cache.local/stations-v1";
}

async function loadStations() {
  const cache = caches.default;
  const cacheRequest = new Request(dirCacheKey());

  const hit = await cache.match(cacheRequest);
  if (hit) {
    return hit.json();
  }

  try {
    const res = await fetch(DIR_URL, {
      headers: {
        "User-Agent": "Mozilla/5.0",
        Accept: "text/html,*/*",
      },
    });

    if (!res.ok) {
      throw new Error(`KMA HTTP ${res.status}`);
    }

    const buf = await res.arrayBuffer();
    let text = null;
    try {
      text = new TextDecoder("euc-kr").decode(buf);
    } catch (e) {
      // TextDecoder 미지원 인코딩
    }

    // EUC-KR 디코딩이 불가능하면 내장 목록 사용
    if (!text || !/[가-힣]/.test(text)) {
      throw new Error("euc-kr decode unavailable");
    }

    const list = parseStationsDir(text);
    if (!list || list.length < 100) {
      throw new Error(`stations parse fail (${list ? list.length : 0})`);
    }

    const cached = new Response(JSON.stringify(list), {
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": `public, max-age=${DIR_CACHE_TTL}`,
      },
    });
    await cache.put(cacheRequest, cached);

    return list;
  } catch (err) {
    return STATIONS; // 내장 fallback
  }
}

function parseStationsDir(html) {
  const rows = html.match(/<tr [\s\S]*?<\/tr>/gi) || [];
  const list = [];

  for (const row of rows) {
    const cells =
      row.match(/<td[\s\S]*?<\/td>/gi) || [];

    if (cells.length < 18) {
      continue;
    }

    const values = cells.map((cell) =>
      cell
        .replace(/<[^>]*>/g, "")
        .replace(/&nbsp;/gi, "")
        .trim()
    );

    const code = values[0];
    const address = values[values.length - 1];

    // 지점번호는 2~3자리 숫자
    if (!/^\d{2,3}$/.test(code)) {
      continue;
    }

    // 주소는 한글이 반드시 포함되어야 함 (파싱 실패 가드)
    if (!/[가-힣]/.test(address)) {
      continue;
    }

    list.push({ c: code, n: values[1], a: address });
  }

  return list;
}

// ======================================================
// 관측소 분 단위 페이지 (기존 스크래핑 로직)
// ======================================================

function stationPageUrl(code) {
  return `https://www.kma.go.kr/cgi-bin/aws/nph-aws_txt_min?0&0&MINDB_01M&${code}&a`;
}

async function fetchStationObservation(code) {
  const response = await fetch(stationPageUrl(code), {
    method: "GET",
    headers: {
      "User-Agent": "Mozilla/5.0",
      Accept: "text/html,*/*",
    },
  });

  if (!response.ok) {
    throw new Error(`KMA HTTP ${response.status}`);
  }

  const html = await response.text();

  const weather = parseKma(html, code);

  if (!weather) {
    throw new Error("유효한 기상 데이터를 찾을 수 없습니다.");
  }

  return weather;
}

function parseKma(html, code) {
  const rows = html.match(/<tr[\s\S]*?<\/tr>/gi) || [];
  const data = [];

  for (const row of rows) {
    const timeMatch = row.match(/<a[^>]*>(\d{2}:\d{2})<\/a>/i);
    if (!timeMatch) continue;

    const time = timeMatch[1];
    const cells = row.match(/<td[\s\S]*?<\/td>/gi) || [];

    if (cells.length < 17) continue;

    const values = cells.map((cell) =>
      cell
        .replace(/<[^>]*>/g, "")
        .replace(/&nbsp;/gi, "")
        .trim()
    );

    // KMA 실제 컬럼 (분 단위 페이지 기준)
    const temperature = Number(values[8]);
    const humidity = Number(values[15]);

    if (!Number.isFinite(temperature) || !Number.isFinite(humidity)) {
      continue;
    }

    data.push({ time, temperature, humidity });
  }

  if (data.length === 0) {
    return null;
  }

  const latest = data[0];

  const dateMatch = html.match(
    /(\d{4})\.(\d{2})\.(\d{2})\.(\d{2}):(\d{2})/
  );

  let date = null;
  if (dateMatch) {
    date = `${dateMatch[1]}-${dateMatch[2]}-${dateMatch[3]}`;
  }

  return {
    station: code,
    date,
    time: latest.time,
    temperature: latest.temperature,
    humidity: latest.humidity,
    source: "KMA AWS",
  };
}

// ======================================================
// 풍속 조회 (공공데이터포털 - 초단기실황) + 체감온도
// ======================================================

const VILAGE_FCST_URL =
  "https://apis.data.go.kr/1360000/VilageFcstInfoService_2.0/getUltraSrtNcst";

function getBaseDateTime() {
  const now = new Date(Date.now() + 9 * 60 * 60 * 1000); // KST

  let hour = now.getUTCHours();
  let date = new Date(now);

  if (now.getUTCMinutes() < 10) {
    date = new Date(now.getTime() - 60 * 60 * 1000);
    hour = date.getUTCHours();
  }

  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  const h = String(hour).padStart(2, "0");

  return {
    base_date: `${y}${m}${d}`,
    base_time: `${h}00`,
  };
}

/**
 * @param {WorkerEnv} env
 * @param {number} nx
 * @param {number} ny
 */
async function fetchWindSpeed(env, nx, ny) {
  if (!env.KMA_SERVICE_KEY) {
    throw new Error(
      `KMA_SERVICE_KEY 바인딩 자체가 비어있음 (env.KMA_SERVICE_KEY = ${JSON.stringify(env.KMA_SERVICE_KEY)})`
    );
  }

  const serviceKey = await env.KMA_SERVICE_KEY.get();

  if (!serviceKey || typeof serviceKey !== "string") {
    throw new Error(
      `Secret Store에서 값을 못 가져옴 (serviceKey = ${JSON.stringify(serviceKey)})`
    );
  }

  const { base_date, base_time } = getBaseDateTime();

  const url =
    `${VILAGE_FCST_URL}` +
    `?serviceKey=${serviceKey}` +
    `&numOfRows=20&pageNo=1&dataType=JSON` +
    `&base_date=${base_date}&base_time=${base_time}` +
    `&nx=${nx}&ny=${ny}`;

  const debugUrl = url.replace(
    serviceKey,
    `${serviceKey.slice(0, 6)}...${serviceKey.slice(-4)}(len${serviceKey.length})`
  );

  const res = await fetch(url);

  if (!res.ok) {
    const bodyText = await res.text().catch(() => "");
    throw new Error(
      `공공데이터포털 HTTP ${res.status} / 요청URL: ${debugUrl} / body: ${bodyText.slice(0, 200)}`
    );
  }

  const data = await res.json();

  const resultCode = data?.response?.header?.resultCode;
  if (resultCode !== "00") {
    throw new Error(
      `공공데이터포털 오류: ${data?.response?.header?.resultMsg || resultCode}`
    );
  }

  const items = data?.response?.body?.items?.item || [];
  const wsdItem = items.find((item) => item.category === "WSD");

  if (!wsdItem) {
    throw new Error("WSD(풍속) 항목을 찾지 못했습니다.");
  }

  return Number(wsdItem.obsrValue);
}

// Stull(2011) 습구온도 근사식 (라디안 그대로 사용)
function calcWetBulb(Ta, RH) {
  return (
    Ta * Math.atan(0.151977 * Math.sqrt(RH + 8.313659)) +
    Math.atan(Ta + RH) -
    Math.atan(RH - 1.676331) +
    0.00391838 * Math.pow(RH, 1.5) * Math.atan(0.023101 * RH) -
    4.686035
  );
}

function calcFeelsLike(temperature, humidity, windSpeedMs) {
  const Ta = Number(temperature);
  const RH = Number(humidity);

  if (!Number.isFinite(Ta) || !Number.isFinite(RH)) {
    return null;
  }

  const month = new Date(Date.now() + 9 * 60 * 60 * 1000).getUTCMonth() + 1;
  const isSummer = month >= 5 && month <= 9;

  if (isSummer) {
    const Tw = calcWetBulb(Ta, RH);
    const feels =
      -0.2442 +
      0.55399 * Tw +
      0.45535 * Ta -
      0.0022 * Tw * Tw +
      0.00278 * Tw * Ta +
      3.0;
    return Math.round(feels * 10) / 10;
  }

  if (Ta <= 10 && Number.isFinite(windSpeedMs) && windSpeedMs >= 1.3) {
    const V = windSpeedMs * 3.6;
    const feels =
      13.12 +
      0.6215 * Ta -
      11.37 * Math.pow(V, 0.16) +
      0.3965 * Math.pow(V, 0.16) * Ta;
    return Math.round(feels * 10) / 10;
  }

  return Ta;
}

// ======================================================
// 히스토리 (Workers KV) — 지점별 분리
// ======================================================

/**
 * @param {WorkerEnv} env
 * @param {string} code
 * @param {{ time: string; [key: string]: unknown }} entry
 */
async function updateHistory(env, code, entry) {
  const kvKey = `history:${code}`;
  const raw = await env.WEATHER_HISTORY.get(kvKey);
  let history = raw ? JSON.parse(raw) : [];

  const isDuplicate =
    history.length > 0 && history[0].time === entry.time;

  if (!isDuplicate) {
    history.unshift(entry);
    history = history.slice(0, HISTORY_MAX_LEN);
    await env.WEATHER_HISTORY.put(kvKey, JSON.stringify(history));
  }

  return history;
}

// ======================================================
// JSON / CORS
// ======================================================

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data, null, 2), {
    status,
    headers: {
      ...CORS_HEADERS,
      "Content-Type": "application/json; charset=utf-8",
    },
  });
}

function addCorsHeaders(response) {
  const headers = new Headers(response.headers);
  headers.set("Access-Control-Allow-Origin", "*");
  headers.set("Access-Control-Allow-Methods", "GET, OPTIONS");
  return new Response(response.body, { status: response.status, headers });
}
